-- 假设 users 表有 balance 字段，金额用 DECIMAL(12,2)
START TRANSACTION;
SELECT balance FROM users WHERE id = 1 FOR UPDATE;
UPDATE users SET balance = balance - 100.00 WHERE id = 1 AND balance >= 100.00;
UPDATE users SET balance = balance + 100.00 WHERE id = 2;
COMMIT;

START TRANSACTION;
UPDATE products SET stock = stock - 1 WHERE id = 1001 AND stock >= 1;
SELECT ROW_COUNT();
UPDATE orders SET status = 'paid' WHERE id = 90001;
-- 若 ROW_COUNT() 为 0（库存不足），应用层直接回滚
ROLLBACK;
